cat > Permission.java <<'EOF'
package net.officefloor.hq.app.settings;

import java.util.Set;

/** An action whose roles the sheet's permission matrix sets, with the roles that may take it when
 *  the matrix leaves it blank. */
public enum Permission {
    OPEN(Set.of(Role.CLERK, Role.STEWARD)),
    SETTLE(Set.of(Role.CLERK, Role.STEWARD)),
    VOID(Set.of(Role.CLERK, Role.STEWARD)),
    REASSIGN(Set.of(Role.STEWARD)),
    CLOSE(Set.of(Role.CLERK, Role.STEWARD)),
    REOPEN(Set.of(Role.STEWARD));

    private final Set<Role> standing;

    Permission(Set<Role> standing) {
        this.standing = standing;
    }

    /** The roles that may take the action when the matrix leaves it blank. */
    public Set<Role> standing() {
        return standing;
    }

    /** The action as it is stored, and as its setting's key follows {@code perm-}. */
    public String key() {
        return name().toLowerCase();
    }

    public static Permission of(String key) {
        return valueOf(key.toUpperCase());
    }
}
EOF
cat > SheetPermission.java <<'EOF'
package net.officefloor.hq.app.settings;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.Id;
import jakarta.persistence.IdClass;
import jakarta.persistence.Table;
import java.io.Serializable;
import java.util.Arrays;
import java.util.EnumSet;
import java.util.Set;

/** The roles that may take an action on a sheet, as its permission matrix sets them. */
@Entity
@Table(name = "sheet_permission")
@IdClass(SheetPermission.Key.class)
public class SheetPermission {

    public record Key(String sheetId, String action) implements Serializable {
        public Key() {
            this(null, null);
        }
    }

    @Id
    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Id
    @Column(name = "action", nullable = false)
    private String action;

    /** The roles, comma separated, as they were set. */
    @Column(name = "roles", nullable = false)
    private String roles;

    protected SheetPermission() {
    }

    public SheetPermission(String sheetId, Permission action, String roles) {
        this.sheetId = sheetId;
        this.action = action.key();
        this.roles = roles;
    }

    public Permission getAction() {
        return Permission.of(action);
    }

    public String getRoles() {
        return roles;
    }

    public void setRoles(String roles) {
        this.roles = roles;
    }

    /** The roles that may take the action. */
    public Set<Role> roleSet() {
        Set<Role> out = EnumSet.noneOf(Role.class);
        Arrays.stream(roles.split(",")).map(String::trim).filter(r -> !r.isEmpty()).map(Role::of).forEach(out::add);
        return out;
    }
}
EOF
